 let mazeGenerator;
        let mazeRenderer;
        let settings;
        let compilationShader;
        let mirrorShader;
        let mazes = [];
        let solutions = [];
        let secondPaths = [];
        let flipStates = [];
        let flippedPathStates = [];
        let lastTime = 0;
        let compilationShaderWidth = 600;
        let compilationShaderHeight = 800;
        let rng;

        function setup() {

            rng = new RandomGenerator(tokenData.hash);

            compilationShader = new CompilationShader(compilationShaderWidth, compilationShaderHeight);
            mirrorShader = new MirrorShader(compilationShaderWidth, compilationShaderHeight);

            settings = new Settings(rng);
            const values = settings.getValues();

            let canvasWidth, canvasHeight;
            if (windowWidth > windowHeight) {
                canvasHeight = windowHeight;
                canvasWidth = (canvasHeight / compilationShaderHeight) * compilationShaderWidth;
            } else {
                canvasWidth = windowWidth;
                canvasHeight = (canvasWidth / compilationShaderWidth) * compilationShaderHeight;
            }

            createCanvas(canvasWidth, canvasHeight);

            compilationShader.setup(rng);
            mirrorShader.setup();

            randomizeShaderSettings();

            mazeRenderer = new MazeRenderer(values.mazeSize, values.cellSize, values.mazeGridSize, rng);
            mazeRenderer.initializePhaseShifts(values.numMazes);
            mazeRenderer.initializeVisibleSegments(values.numMazes);
            mazeRenderer.initializeSpeeds(values.numMazes);

            regenerateMazes();
            lastTime = millis();
        }

        function mousePressed() { mazeRenderer.animateSolution = !mazeRenderer.animateSolution; return false; }
        function touchStarted() { mazeRenderer.animateSolution = !mazeRenderer.animateSolution; return false; }

        function randomizeShaderSettings() {
            const segments = [1, 2, 4, 6];
            const randomSegments = segments[Math.floor(rng.random() * segments.length)];
            mirrorShader.setKaleidoscopeSegments(randomSegments);
            compilationShader.randomizeSettings(rng);
        }

        function generateFlippedPathStates(numMazes, pathFlipOption) {
            switch (pathFlipOption) {
                case 'always': return new Array(numMazes).fill(true);
                case 'random': return new Array(numMazes).fill(0).map(() => rng.randomChance());
                default: return new Array(numMazes).fill(false);
            }
        }

        function initializeFlipStates() {
            const values = settings.getValues();
            flipStates = [];
            for (let y = 0; y < values.mazeGridSize; y++) {
                for (let x = 0; x < values.mazeGridSize; x++) {
                    flipStates.push(getFlipState(x, y, values.mazeGridSize, values.flipOption || 'none'));
                }
            }
        }

        function getFlipState(x, y, gridSize, flipOption) {
            switch (flipOption) {
                case 'random': return {
                    flipH: rng.randomChance(),
                    flipV: rng.randomChance()
                };
                case 'alternate': return {
                    flipH: (x + y) % 2 === 0,
                    flipV: (x + y) % 2 === 1
                };
                case 'horizontal': return {
                    flipH: y % 2 === 0,
                    flipV: false
                };
                case 'vertical': return {
                    flipH: false,
                    flipV: x % 2 === 0
                };
                case 'checkerboard': return {
                    flipH: (x + y) % 2 === 0,
                    flipV: (x + y) % 2 === 0
                };
                default: return {
                    flipH: false,
                    flipV: false
                };
            }
        }

        function regenerateMazes() {
            const values = settings.getValues();
            mazeRenderer.initializePhaseShifts(values.numMazes);
            mazeRenderer.initializeVisibleSegments(values.numMazes);
            mazeRenderer.initializeSpeeds(values.numMazes);

            mazes = [];
            solutions = [];
            secondPaths = [];
            for (let i = 0; i < values.numMazes; i++) {
                mazeGenerator = new MazeGenerator(values.mazeSize);
                const maze = mazeGenerator.generate();
                mazes.push(maze);
                const solution = mazeGenerator.solve(maze);
                solutions.push(solution);
                const secondPathSegments = mazeGenerator.generateSecondPath(solution);
                secondPaths.push(secondPathSegments);
            }

            initializeFlipStates();
            flippedPathStates = generateFlippedPathStates(values.numMazes, values.pathFlipOption);
            randomizeShaderSettings();
        }

        function draw() {
            background(220);


            if (mazeRenderer.animateSolution) {
                mazeRenderer.updateAnimation();
            }

            const values = settings.getValues();
            mazeRenderer.render(mazes, solutions, secondPaths, values, flipStates, flippedPathStates);

            compilationShader.setSize(values.compilationWidth, values.compilationHeight);
            compilationShader.setGridSize(values.gridSize);
            compilationShader.setCompilationAspectRatio(values.compilationWidth / values.compilationHeight);
            compilationShader.setMazeAspectRatio(1);
            compilationShader.setMazeGridSize(values.mazeGridSize);

            compilationShader.updateTime();
            compilationShader.updateUniforms(mazeRenderer.getCanvas());
            compilationShader.draw();

            mirrorShader.draw(compilationShader.getGraphics());

            const mirrorGraphics = mirrorShader.getGraphics();
            const mazeCanvas = mazeRenderer.getCanvas();

            if (mirrorGraphics) {
                image(mirrorGraphics, 0, 0, width, height);
            }

        }

        function windowResized() {
            if (windowWidth > windowHeight) {
                canvasHeight = windowHeight * 0.95;
                canvasWidth = (canvasHeight / compilationShaderHeight) * compilationShaderWidth;
            } else {
                canvasWidth = windowWidth * 0.95;
                canvasHeight = (canvasWidth / compilationShaderWidth) * compilationShaderHeight;
            }

            resizeCanvas(canvasWidth, canvasHeight);
            compilationShader.setSize(canvasWidth, canvasHeight);
            mirrorShader.setSize(canvasWidth, canvasHeight);
        }

        class MazeGenerator {
            constructor(size) {
                this.size = size;
                this.maze = [];
                this.rng = rng;
            }

            generate() {
                this.maze = new Array(this.size).fill().map(() => new Array(this.size).fill(15));

                const carve = (x, y) => {
                    // Create directions array
                    const directions = [
                        [0, -1, 1],
                        [1, 0, 2],
                        [0, 1, 4],
                        [-1, 0, 8]
                    ];
                    
                    // Simple random ordering - no fancy shuffling
                    const order = [];
                    if (this.rng.random() < 0.25) {
                        order.push(1, 0, 2, 3);
                    } else if (this.rng.random() < 0.33) {
                        order.push(1, 0, 3, 2);
                    } else if (this.rng.random() < 0.5) {
                        order.push(2, 3, 0, 1);
                    } else {
                        order.push(3, 2, 1, 0);
                    }
                    
                    // Process directions in the random order
                    for (let i = 0; i < order.length; i++) {
                        const idx = order[i];
                        const dx = directions[idx][0];
                        const dy = directions[idx][1];
                        const wall = directions[idx][2];
                        
                        let nx = x + dx, ny = y + dy;
                        if (nx >= 0 && ny >= 0 && nx < this.size && ny < this.size && this.maze[ny][nx] === 15) {
                            this.maze[y][x] &= ~wall;
                            this.maze[ny][nx] &= ~(wall << 2) % 15;
                            carve(nx, ny);
                        }
                    }
                };

                carve(0, 0);
                return this.maze;
            }

            generateSecondPath(mainSolution) {

                let visited = new Array(this.size).fill().map(() => new Array(this.size).fill(false));
                let secondPaths = [];


                for (let [x, y] of mainSolution) {
                    visited[y][x] = true;
                }

                const directions = [
                    [0, -1, 1, 4],  // Up
                    [1, 0, 2, 8],   // Right
                    [0, 1, 4, 1],   // Down
                    [-1, 0, 8, 2]   // Left
                ];

                const bfs = (startX, startY) => {
                    let queue = [[startX, startY]];
                    let path = [];
                    let parent = new Map();

                    visited[startY][startX] = true;

                    while (queue.length > 0) {
                        let [x, y] = queue.shift();
                        path.push([x, y]);

                        for (let [dx, dy, wall, oppositeWall] of directions) {
                            let nx = x + dx, ny = y + dy;
                            if (nx >= 0 && ny >= 0 && nx < this.size && ny < this.size &&
                                !visited[ny][nx] && !(this.maze[y][x] & wall) && !(this.maze[ny][nx] & oppositeWall)) {
                                visited[ny][nx] = true;
                                queue.push([nx, ny]);
                                parent.set(`${nx},${ny}`, [x, y]);
                            }
                        }
                    }


                    let fullPath = [];
                    let current = path[path.length - 1];
                    while (current) {
                        fullPath.unshift(current);
                        current = parent.get(current.join(','));
                    }

                    return fullPath;
                };


                for (let y = 0; y < this.size; y++) {
                    for (let x = 0; x < this.size; x++) {
                        if (!visited[y][x]) {
                            let pathSegment = bfs(x, y);
                            if (pathSegment.length > 1) {
                                secondPaths.push(pathSegment);
                            }
                        }
                    }
                }


                return secondPaths;
            }


            solve() {
                let visited = new Array(this.size).fill().map(() => new Array(this.size).fill(false));
                let path = [];

                const dfs = (x, y) => {
                    if (x < 0 || y < 0 || x >= this.size || y >= this.size || visited[y][x]) {
                        return false;
                    }

                    visited[y][x] = true;
                    path.push([x, y]);

                    if (x === this.size - 1 && y === this.size - 1) {
                        return true;
                    }

                    const directions = [[0, -1, 1], [1, 0, 2], [0, 1, 4], [-1, 0, 8]];
                    for (let [dx, dy, wall] of directions) {
                        if (!(this.maze[y][x] & wall)) {
                            if (dfs(x + dx, y + dy)) {
                                return true;
                            }
                        }
                    }

                    path.pop();
                    return false;
                };

                dfs(0, 0);
                return path;
            }
        }

        class MazeRenderer {
            constructor(size, cellSize, gridSize) {
                this.rng = rng;
                this.size = size;
                this.cellSize = cellSize;
                this.gridSize = gridSize;
                const totalSize = this.size * this.cellSize * this.gridSize;
                this.canvas = createGraphics(totalSize, totalSize);
                this.currentStartSegment = 0;
                this.totalSegments = 500;
                this.phaseShifts = [];
                this.visibleSegmentsPerMaze = [];
                this.minVisibleSegments = 250;
                this.maxVisibleSegments = 500;
                this.speedsPerMaze = [];
                this.currentStartSegments = [];
                this.minSpeed = 0.5;
                this.maxSpeed = 1.5;
                this.animateSolution = false;
                this.colorLerpFactor = 0;
                this.colorAnimationAngle = 0;
            }
            updateAnimation() {

                for (let i = 0; i < this.currentStartSegments.length; i++) {
                    this.currentStartSegments[i] = (this.currentStartSegments[i] + this.speedsPerMaze[i]) % this.totalSegments;
                }
                this.updateColorAnimation();
            }

            updateColorAnimation() {
                this.colorAnimationAngle += 0.0005;
                if (this.colorAnimationAngle > TWO_PI) {
                    this.colorAnimationAngle -= TWO_PI;
                }

            }

            setAnimationSpeed(speed) {
                this.animationSpeed = speed;
            }

            initializePhaseShifts(numMazes) {
                this.phaseShifts = Array(numMazes).fill(0).map(() =>
                    Math.floor(this.rng.random() * this.totalSegments)
                );
            }

            initializeVisibleSegments(numMazes) {
                this.visibleSegmentsPerMaze = Array(numMazes).fill(0).map(() =>
                    Math.floor(this.rng.random() * (this.maxVisibleSegments - this.minVisibleSegments + 1)) + this.minVisibleSegments
                );
            }

            initializeSpeeds(numMazes) {
                this.speedsPerMaze = Array(numMazes).fill(0).map(() =>
                    this.minSpeed + this.rng.random() * (this.maxSpeed - this.minSpeed)
                );
                this.currentStartSegments = Array(numMazes).fill(0);
            }

            render(mazes, solutions, secondPaths, options, flipStates, flippedPathStates) {
                const totalSize = this.size * this.cellSize * this.gridSize;
                this.canvas.clear();  // Clear the existing canvas instead of creating a new one
                this.canvas.background(options.backgroundColor);


                for (let y = 0; y < this.gridSize; y++) {
                    for (let x = 0; x < this.gridSize; x++) {
                        const index = y * this.gridSize + x;
                        const mazeIndex = index % mazes.length;

                        const flipState = flipStates[index];
                        const showFlippedPath = flippedPathStates[mazeIndex];

                        this.canvas.push();
                        this.canvas.translate(x * this.size * this.cellSize, y * this.size * this.cellSize);

                        if (flipState.flipH) {
                            this.canvas.scale(-1, 1);
                            this.canvas.translate(-this.size * this.cellSize, 0);
                        }
                        if (flipState.flipV) {
                            this.canvas.scale(1, -1);
                            this.canvas.translate(0, -this.size * this.cellSize);
                        }

                        if (options.showWalls) {
                            this.drawMaze(mazes[mazeIndex], options, flipState);
                        }

                        if (options.showPath) {
                            this.drawSolution(solutions[mazeIndex], options, showFlippedPath, this.phaseShifts[mazeIndex], mazeIndex, options.animateSolution);
                        }


                        if (options.showSecondPath && !showFlippedPath) {
                            const mazeGenerator = new MazeGenerator(this.size);
                            mazeGenerator.maze = mazes[mazeIndex];
                            const secondPathForMaze = mazeGenerator.generateSecondPath(solutions[mazeIndex], flipState);
                            this.drawSecondPath(secondPathForMaze, options);
                        }

                        this.canvas.pop();
                    }
                }
            }

            updateProperties(size, cellSize, gridSize) {
                if (this.size !== size || this.cellSize !== cellSize || this.gridSize !== gridSize) {
                    this.size = size;
                    this.cellSize = cellSize;
                    this.gridSize = gridSize;
                    const totalSize = this.size * this.cellSize * this.gridSize;
                    this.canvas.resizeCanvas(totalSize, totalSize);
                }
            }

            drawMaze(maze, options) {
                this.canvas.stroke(options.lineColor);
                this.canvas.strokeWeight(options.lineWeight || 1);
                for (let y = 0; y < this.size; y++) {
                    for (let x = 0; x < this.size; x++) {
                        let cell = maze[y][x];
                        let X = x * this.cellSize;
                        let Y = y * this.cellSize;

                        if (cell & 1) this.canvas.line(X, Y, X + this.cellSize, Y);
                        if (cell & 2) this.canvas.line(X + this.cellSize, Y, X + this.cellSize, Y + this.cellSize);
                        if (cell & 4) this.canvas.line(X, Y + this.cellSize, X + this.cellSize, Y + this.cellSize);
                        if (cell & 8) this.canvas.line(X, Y, X, Y + this.cellSize);
                    }
                }
            }

            drawSolution(solution, options, showFlippedPath = false, phaseShift = 0, mazeIndex) {
                if (this.animateSolution) {

                    this.drawAnimatedPath(solution, options, showFlippedPath, phaseShift, mazeIndex);
                } else {

                    this.drawFullPath(solution, options, showFlippedPath);
                }
            }

            drawAnimatedPath(solution, options, showFlippedPath, phaseShift, mazeIndex) {

                this.drawPathWithOutline(solution, options, false, phaseShift, mazeIndex);


                if (showFlippedPath) {
                    this.drawPathWithOutline(solution, options, true, phaseShift, mazeIndex);
                }
            }

            drawFullPath(solution, options, showFlippedPath) {

                this.canvas.stroke(options.pathColor1);
                this.canvas.strokeWeight(options.pathWeight1);
                this.drawPath(solution, false);


                this.canvas.stroke(options.pathColor2);
                this.canvas.strokeWeight(options.pathWeight2);
                this.drawPath(solution, false);

                if (showFlippedPath) {

                    this.canvas.stroke(options.pathColor1);
                    this.canvas.strokeWeight(options.pathWeight1);
                    this.drawPath(solution, true);


                    this.canvas.stroke(options.pathColor2);
                    this.canvas.strokeWeight(options.pathWeight2);
                    this.drawPath(solution, true);
                }
            }

            drawPathWithOutline(solution, options, flipped, phaseShift, mazeIndex) {

                let animatedColor = lerpColor(color(options.pathColor1), color(options.pathColor2), this.colorLerpFactor);
                this.canvas.stroke(animatedColor);
                this.canvas.strokeWeight(options.pathWeight1);

                this.drawPartialPath(solution, flipped, phaseShift, mazeIndex);


                this.canvas.stroke(options.pathColor2);
                this.canvas.strokeWeight(options.pathWeight2);
                this.drawPartialPath(solution, flipped, phaseShift, mazeIndex);
            }


            drawPartialPath(solution, flipped, phaseShift, mazeIndex) {

                const visibleSegments = this.visibleSegmentsPerMaze[mazeIndex];
                const totalLength = solution.length;

                this.canvas.noFill();
                this.canvas.beginShape();

                let lastX, lastY;
                let isFirstPoint = true;

                for (let i = 0; i < visibleSegments; i++) {
                    const segmentIndex = (this.currentStartSegments[mazeIndex] + i + phaseShift) % this.totalSegments;
                    const t = (segmentIndex % this.totalSegments) / this.totalSegments;
                    const exactIndex = t * (totalLength - 1);
                    const index1 = Math.floor(exactIndex);
                    const index2 = (index1 + 1) % totalLength;
                    const subT = exactIndex - index1;

                    const [x1, y1] = solution[index1];
                    const [x2, y2] = solution[index2];

                    const x = x1 + (x2 - x1) * subT;
                    const y = y1 + (y2 - y1) * subT;

                    const X = flipped ? this.size * this.cellSize - (x * this.cellSize + this.cellSize / 2) : x * this.cellSize + this.cellSize / 2;
                    const Y = y * this.cellSize + this.cellSize / 2;

                    if (!isFirstPoint && this.shouldStartNewShape(lastX, lastY, X, Y)) {
                        this.canvas.endShape();
                        this.canvas.beginShape();
                    }

                    this.canvas.vertex(X, Y);
                    lastX = X;
                    lastY = Y;
                    isFirstPoint = false;
                }

                this.canvas.endShape();
            }

            shouldStartNewShape(x1, y1, x2, y2) {
                const distance = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
                return distance > this.cellSize * 2;
            }


            drawPath(solution, flipped) {
                this.canvas.noFill();
                this.canvas.beginShape();
                for (let [x, y] of solution) {
                    const X = flipped ? this.size * this.cellSize - (x * this.cellSize + this.cellSize / 2) : x * this.cellSize + this.cellSize / 2;
                    const Y = y * this.cellSize + this.cellSize / 2;
                    this.canvas.vertex(X, Y);
                }
                this.canvas.endShape();
            }

            drawSecondPath(paths, options, flipH, flipV) {
                this.canvas.stroke(options.secondPathColor);
                this.canvas.strokeWeight(options.secondPathWeight);
                this.canvas.noFill();

                for (let path of paths) {
                    this.canvas.beginShape();
                    for (let [x, y] of path) {
                        let X = x * this.cellSize + this.cellSize / 2;
                        let Y = y * this.cellSize + this.cellSize / 2;
                        if (flipH) X = this.size * this.cellSize - X;
                        if (flipV) Y = this.size * this.cellSize - Y;
                        this.canvas.vertex(X, Y);
                    }
                    this.canvas.endShape();
                }
            }

            getCanvas() {
                return this.canvas;
            }
        }

        class CompilationShader {
            constructor(width = 600, height = 800) {
                this.width = width;
                this.height = height;
                this.shader = null;
                this.graphics = null;
                this.previousFrame = null;
                this.vertexShader = null;
                this.fragmentShader = null;
                this.gridSize = 2;
                this.mazeAspectRatio = 1.33;
                this.time = 0;
                this.rippleStrength = 0.2;
                this.rippleFrequency = 2.0;
                this.pulseIntensity = 3.0;
                this.pulseFrequency = 0.1;
                this.mazeGridSize = 4;
                this.trailIntensity = 0.0;
                this.flipHorizontalProbability = 0.5;
                this.flipVerticalProbability = 0.5;

                this.vertexShaderSource = `
        attribute vec3 aPosition;
        attribute vec2 aTexCoord;
        
        varying vec2 vTexCoord;
        
        void main() {
            vTexCoord = aTexCoord;
            vec4 positionVec4 = vec4(aPosition, 1.0);
            positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
            gl_Position = positionVec4;
        }
        `;

                this.fragmentShaderSource = `
            precision mediump float;

            varying vec2 vTexCoord;

            uniform vec2 resolution;
            uniform int gridSize;
            uniform sampler2D mazeTexture;
            uniform sampler2D previousFrame;
            uniform float compilationAspectRatio;
            uniform float time;
            uniform float rippleStrength;
            uniform float rippleFrequency;
            uniform float pulseIntensity;
            uniform float pulseFrequency;
            uniform float zoomFactor;
            uniform float fractalDepth;
            uniform int mazeGridSize;
            uniform float trailIntensity;
            uniform float flipHorizontalProbability;
            uniform float flipVerticalProbability;

            float rand(vec2 co) {
                return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
            }

            vec4 gaussianBlur(sampler2D image, vec2 uv, vec2 resolution, float sigma) {
                vec4 color = vec4(0.0);
                float total = 0.0;
                
                const int samples = 15;
                
                for (int x = -samples / 2; x <= samples / 2; x++) {
                    for (int y = -samples / 2; y <= samples / 2; y++) {
                        vec2 offset = vec2(float(x), float(y)) / resolution;
                        float weight = exp(-(float(x)*float(x) + float(y)*float(y)) / (2.0 * sigma * sigma));
                        color += texture2D(image, uv + offset) * weight;
                        total += weight;
                    }
                }
                
                return color / total;
            }

            vec4 hardLight(vec4 base, vec4 blend) {
                vec4 result;
                result.rgb = mix(
                    2.0 * base.rgb * blend.rgb,
                    1.0 - 2.0 * (1.0 - base.rgb) * (1.0 - blend.rgb),
                    step(0.5, blend.rgb)
                );
                result.a = base.a;
                return result;
            }

           
            vec2 fractalZoom(vec2 uv, float zoom) {
                vec2 center = vec2(0.5);
                uv = (uv - center) * zoom + center;
                return mod(uv, 1.0);
            }

            vec2 applyMovement(vec2 uv, vec2 index, float time, float speed) {
                if (index.y < 0.5) {
                    uv.y = mod(uv.y - time * speed, 1.0);
                } else {
                    uv.y = mod(uv.y + time * speed, 1.0);
                }
                if (index.x < 0.5) {
                    uv.x = mod(uv.x - time * speed, 1.0);
                } else {
                    uv.x = mod(uv.x + time * speed, 1.0);
                }
                return uv;
            }

            void main() {
                vec2 uv = vTexCoord;
                
                float distanceFromCenter = length(uv - 0.5);
                float ripple = sin(distanceFromCenter * rippleFrequency - time) * rippleStrength;

                if (compilationAspectRatio > 1.0) {
                    float scale = 1.0 / compilationAspectRatio;
                    uv.y = (uv.y - 0.5) / scale + 0.5;
                } else {
                    uv.x = (uv.x - 0.5) * compilationAspectRatio + 0.5;
                }
                
                bool flipVertical = false;
                if (uv.y < 0.0 || uv.y > 1.0) {
                    uv.y = mod(uv.y, 1.0);
                    flipVertical = true;
                }
                
                float gridSpeed = 0.005;
                float yOffset = time * gridSpeed;

                float column = floor(uv.x * float((mazeGridSize*2)));

                if (mod(column, 2.0) == 1.0) {
                    yOffset = -yOffset;
                }

                float animatedY = fract(uv.y + yOffset);
                
                vec2 mazeSize = vec2(1.0 / float(gridSize));
                vec2 mazeIndex = floor(uv / mazeSize);
                vec2 mazeUV = fract(uv / mazeSize);
                
                float randomValue = rand(vec2(floor(mazeIndex.x), floor(mazeIndex.y)));

                if (mod(mazeIndex.x, 2.0) == 1.0) {
                    mazeUV.x = 1.0 - mazeUV.x;
                }

                if (mod(mazeIndex.y, 2.0) == 1.0  && flipVerticalProbability < 0.5) {
                mazeUV.y = 1.0 - mazeUV.y;
                }
            
                vec4 mazeColor = texture2D(mazeTexture, mazeUV);
                float pulse = 1.0 + pulseIntensity * sin(time * pulseFrequency);
                pulse += 0.2;

                vec4 blurredColor = gaussianBlur(mazeTexture, mazeUV, resolution, 15.0);
                vec4 hardLightColor = hardLight(mazeColor, mazeColor);
                float noise = rand(uv) * 0.99;
                
                vec4 finalColor = mix(hardLightColor, vec4(vec3(noise), 1.0), 0.1);
                vec4 noisemix = mix(mazeColor, finalColor, 0.9);
                
                vec4 previousColor = texture2D(previousFrame, vTexCoord);
                noisemix = max(noisemix, previousColor * trailIntensity);

                gl_FragColor = noisemix;
            }
        `;


            }

            setMazeGridSize(size) {
                this.mazeGridSize = size;
