                    [255, 215, 0],   // Gold
                    [0, 206, 209],   // Turquoise
                    [0, 0, 0]        // Black
                ];

                const colors = baseColors.map(color => this.rgbToHex(this.varyColor(color, 30)));

                return {
                    background: colors[0],
                    line: colors[5],
                    path1: colors[1],
                    path2: colors[2],
                    secondPath: colors[3],
                    border: colors[4]
