            generatePatchworkEarthPalette() {
                const colors = [
                    '#FFA726',
                    '#FFD54F',
                    '#FF7043',
                    '#FB8C00',
                    '#F57C00',
                    '#FFB300'
                ];

                let palette = {
                    background: this.rgbToHex(this.varyColor('#404040', 8)),
                    line: this.rgbToHex(this.varyColor('#E0E0E0', 10)),
                    path1: this.rgbToHex(this.varyColor(colors[Math.floor(this.rng.random() * 3)], 15)),
                    path2: this.rgbToHex(this.varyColor(colors[Math.floor(this.rng.random() * 3) + 3], 15)),
                    secondPath: this.rgbToHex(this.varyColor(colors[2], 15)),
                    border: this.rgbToHex(this.varyColor('#BDBDBD', 8))
                };


                const bgRgb = this.hexToRgb(palette.background);
                const minContrastRatio = 3.5;


                Object.keys(palette).forEach(key => {
                    if (key === 'background') return;

                    const rgb = this.hexToRgb(palette[key]);
                    if (this.getContrastRatio(bgRgb, rgb) < minContrastRatio) {

                        const brighterColor = rgb.map(c => Math.min(255, c + 40));
                        palette[key] = this.rgbToHex(brighterColor);
                    }
                });


                if (palette.path1 === palette.path2 ||
                    this.getContrastRatio(this.hexToRgb(palette.path1), this.hexToRgb(palette.path2)) < 1.5) {
                    palette.path2 = this.rgbToHex(this.varyColor(colors[colors.length - 1], 15));
                }

                return palette;
